//
// Do not flush.
//
// If `withNamespace` is set, the `xmlns` attribute is set in the XML element
// to [Namespace].
func writeClass(
	encoder *xml.Encoder,
	that aastypes.IClass,
	withNamespace bool,
) (err error) {
	switch that.ModelType() {
	case aastypes.ModelTypeSomething:
		err = writeClassElement(
			encoder,
			"something",
			withNamespace,
			that.(aastypes.ISomething),
			writeSomethingAsSequence,
		)
	default:
		err = xmlcommon.NewSerializationError(
			fmt.Sprintf(
				"Unexpected model type: %v",
				that.ModelType(),
			),
		)
	}
	return
}

// Serialize `that` instance as an XML element, and flush the encoder.
//
// If `withNamespace` is set, the `xmlns` attribute is set in the XML element
// to [Namespace].
func Marshal(
	encoder *xml.Encoder,
	that aastypes.IClass,
	withNamespace bool,
) (err error) {
	err = writeClass(encoder, that, withNamespace)
	if err != nil {
		return
	}

	return encoder.Flush()
}

